-- Postgres dialect of schema/0953_jit_eligibility.sql (issue #651, AC-5; kept in parity with the SQLite file by
-- TestSchemaParity_SQLiteAndPostgres). Cross-tenant guard triggers become composite foreign keys
-- (tenant_id, x_id) -> (tenant_id, id); see 0001_tenancy.sql. rls.sql is regenerated by `tessera admin gen-rls`.

-- +goose Up

CREATE TABLE jit_settings (
  tenant_id TEXT NOT NULL REFERENCES tenants (id),
  enabled BIGINT NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)),
  updated_by TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (tenant_id)
);

CREATE TABLE jit_eligibility (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants (id),
  key TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','retired')),
  max_hours BIGINT NOT NULL CHECK (max_hours BETWEEN 1 AND 72),
  min_approvals BIGINT NOT NULL DEFAULT 0 CHECK (min_approvals BETWEEN 0 AND 1),
  step_up BIGINT NOT NULL DEFAULT 0 CHECK (step_up IN (0, 1)),
  version BIGINT NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, key)
);

CREATE TABLE jit_eligibility_groups (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants (id),
  eligibility_id TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('principal','entitlement','approver')),
  group_id BIGINT NOT NULL,
  UNIQUE (tenant_id, eligibility_id, role, group_id),
  FOREIGN KEY (tenant_id, eligibility_id) REFERENCES jit_eligibility (tenant_id, id),
  FOREIGN KEY (tenant_id, group_id) REFERENCES groups (tenant_id, id)
);
CREATE INDEX ix_jit_eligibility_groups_tenant_group ON jit_eligibility_groups (tenant_id, group_id);

CREATE TABLE jit_eligibility_versions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants (id),
  eligibility_id TEXT NOT NULL,
  version BIGINT NOT NULL,
  snapshot TEXT NOT NULL,
  actor TEXT NOT NULL,
  changed_at TEXT NOT NULL,
  policy_ref TEXT,
  UNIQUE (tenant_id, eligibility_id, version),
  FOREIGN KEY (tenant_id, eligibility_id) REFERENCES jit_eligibility (tenant_id, id)
);

CREATE TRIGGER jit_eligibility_versions_no_update BEFORE UPDATE ON jit_eligibility_versions
	FOR EACH ROW EXECUTE FUNCTION tessera_abort('jit_eligibility_versions is append-only');

CREATE TRIGGER jit_eligibility_versions_no_delete BEFORE DELETE ON jit_eligibility_versions
	FOR EACH ROW EXECUTE FUNCTION tessera_abort('jit_eligibility_versions is append-only');
